-- Seed 004 — 30 sản phẩm thương hiệu thật (model/giá/thông số mô phỏng): 10 tủ lạnh, 10 máy giặt, 10 máy lạnh. Chạy sau 003 (cần admin@example.test và 011).
-- FILE SINH TỰ ĐỘNG bởi scripts/generate-seed-data.mjs — đừng sửa tay. Dữ liệu MÔ PHỎNG cho demo.
USE household_ecommerce;


UPDATE product_variants v JOIN inventory_movements m ON m.variant_id = v.id AND m.reference_code = 'SEED-TL-011-01' SET v.stock_quantity = m.quantity_after WHERE v.sku = 'TL-011-01' AND v.stock_quantity = m.quantity_before AND NOT EXISTS (SELECT 1 FROM inventory_movements o WHERE o.variant_id = v.id AND o.id <> m.id);

